import {brandLogos} from './brands.js?v=122';
import {suppliers,stores,CHECKED,SOURCES} from './data.js?v=122';
import {products,productReviews,resolveProductId,lookupReviewedBarcode,catalogueSummary} from './catalogue.js?v=122';
import {validBarcode,miles,cleanBasket,hasOrganicListing,organicEvidenceLabel,decision,alternatives,cutOf,evidenceRecordLabel,retailerCoverage,availabilityLabel,evaluateProduct} from './logic.js?v=122';
import {retailerReviews,retailerResearch,publishedRetailerRankings,organicSources} from './reviews.js?v=122';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let state={route:location.hash.slice(1)||'discover',category:'All meat',search:'',retailer:read('ff-retailer','all'),filter:'all',scope:'supermarkets',verdict:'all',sort:'default',compare:[],strict:read('ff-strict',false),saved:read('ff-saved',[]),basket:read('ff-basket',{}),packChecks:read('ff-pack-checks',{}),barcodeObservations:read('ff-barcode-observations',[]),outdoor:read('ff-outdoor',true),onlySaved:false,storeType:'Supermarket',origin:null};
function migrateIds(value){
 if(!value||typeof value!=='object'||Array.isArray(value))return value;
 return Object.entries(value).reduce((next,[id,quantity])=>{const canonical=resolveProductId(id);next[canonical]=(next[canonical]||0)+quantity;return next},{});
}
state.basket=cleanBasket(migrateIds(state.basket),products.map(p=>p.id));
state.saved=Array.isArray(state.saved)?[...new Set(state.saved.map(resolveProductId).filter(id=>products.some(p=>p.id===id)))]:[];
if(typeof state.outdoor!=='boolean')state.outdoor=true;
if(!Object.hasOwn(retailerReviews,state.retailer))state.retailer='all';
if(typeof state.strict!=='boolean')state.strict=false;
if(!Array.isArray(state.barcodeObservations))state.barcodeObservations=[];
state.barcodeObservations=state.barcodeObservations.filter(x=>x&&typeof x==='object'&&typeof x.id==='string').slice(-100);
const verdict=p=>decision(p,productReviews[p.id],state);
const verdictNames={all:'All catalogue items',meets:'Confirmed match',likely:'Pack check needed',check:'Evidence conflict — check the pack',outside:'Confirmed mismatch',unknown:'Not enough evidence'};

const nav=[['discover','map','Find better meat'],['scan','scan-barcode','Scan & check'],['nearby','map-pin','Nearby'],['suppliers','tractor','Suppliers'],['basket','list-checks','My choices']];
const speciesIcon=s=>s==='Chicken'?'drumstick':s==='Pork'?'utensils':'beef';
function brand(name,small=false){return brandLogos[name]?`<span class="brand-logo ${small?'compact':''}"><img src="${brandLogos[name]}" alt="" width="40" height="40"></span>`:''}
function brandNode(name,small=false){if(!brandLogos[name])return null;const span=document.createElement('span'),img=document.createElement('img');span.className=`brand-logo ${small?'compact':''}`;img.src=brandLogos[name];img.alt='';img.width=40;img.height=40;span.append(img);return span}
function evidenceBadge(p){const r=productReviews[p.id],exact=p.identityStatus==='exact_variant';return `<span class="evidence-badge ${exact?'exact':'candidate'}">${icon(exact?'badge-check':'package-search')}<span><b>${exact?'Exact product review':'Pack check needed'}</b><small>${esc(evidenceRecordLabel(p,r))}</small></span></span>`}
function icons(){window.lucide?.createIcons({attrs:{'stroke-width':1.7}})}
function decorateBranding(){
 document.querySelectorAll('.location-card').forEach(card=>{
  const heading=card.querySelector('h3'); if(!heading||heading.querySelector('.brand-logo')) return;
  const store=stores.find(s=>s.name===heading.textContent.trim()); const logo=store?.retailer&&brandNode(store.retailer,true); if(logo)heading.prepend(logo);
 });
 document.querySelectorAll('.basket-item .item-info > p').forEach(label=>{
  const retailer=label.textContent.trim(),logo=brandNode(retailer,true); if(logo&&!label.querySelector('.brand-logo')) label.prepend(logo);
 });
 const title=$('#dialog-title');
 if(title&&!title.querySelector('.brand-logo')){
 const product=products.find(p=>p.name===title.textContent.trim());
 const supplier=suppliers.find(s=>s.name===title.textContent.trim());
 const retailer=product?.retailer||supplier?.name;
 const logo=brandNode(retailer,true);if(logo) title.prepend(logo);
 if(product){const actions=document.querySelector('.dialog-actions');if(actions&&!actions.querySelector('[data-action="check-pack"]')){const button=document.createElement('button');button.className='btn';button.dataset.action='check-pack';button.dataset.id=product.id;button.textContent='Check this pack';actions.prepend(button)}}
 }
 document.querySelectorAll('.dialog-body .check-row b').forEach(label=>{
  const retailer=label.textContent.trim().split('\n')[0],logo=brandNode(retailer,true); if(logo&&!label.querySelector('.brand-logo')) label.prepend(logo);
 });
 const guide=document.querySelector('.retailer-guide');
 const logo=guide&&state.retailer!=='all'&&brandNode(state.retailer,true);if(logo&&!guide.querySelector('.brand-logo')) guide.prepend(logo);
 document.querySelectorAll('.product-card').forEach(card=>{const productButton=card.querySelector('[data-action="product"]'),actions=card.querySelector('.card-bottom');if(!productButton||!actions||actions.querySelector('[data-action="check-pack"]'))return;const button=document.createElement('button');button.className='text-button';button.dataset.action='check-pack';button.dataset.id=productButton.dataset.id;button.textContent='Pack check';actions.prepend(button)});
}
function guideLanguage(){const hero=$('.shopping-hero');if(hero){hero.querySelector('h2').textContent='Avoid factory-farmed meat.';hero.querySelector('p').textContent='Choose the supermarket you are visiting, then use the evidence to find the better-documented option or rule out a poor fit.'}const picker=document.querySelector('.shop-picker h2');if(picker)picker.textContent='Where are you going?';const pickerHeading=document.querySelector('.shop-picker .catalogue-heading');if(pickerHeading&&!pickerHeading.querySelector('[data-action="published-rankings"]'))pickerHeading.insertAdjacentHTML('beforeend',`<button class="text-button" data-action="published-rankings">Published research rankings ${icon('chart-no-axes-combined')}</button><button class="text-button" data-action="catalogue-audit">Coverage & audit ${icon('clipboard-check')}</button>`);const scanHelp=document.querySelector('.scan-help');if(scanHelp&&!scanHelp.querySelector('[data-action="record-barcode"]'))scanHelp.insertAdjacentHTML('beforeend',`<button class="btn wide" data-action="record-barcode">${icon('clipboard-pen-line')}Record an unreviewed pack</button>${state.barcodeObservations.length?`<button class="text-button" data-action="view-observations">${state.barcodeObservations.length} local pack ${state.barcodeObservations.length===1?'observation':'observations'}</button>`:''}`);document.querySelectorAll('.catalogue-heading h2').forEach(heading=>{if(heading.textContent==='Your supermarket guide')heading.textContent='Your evidence guide'})}
function count(){return Object.values(state.basket).reduce((a,b)=>a+b,0)}
function navigation(){const links=nav.map(([id,i,label])=>`<a class="nav-link ${state.route===id?'active':''}" href="#${id}" ${state.route===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='basket'&&count()?`<span class="nav-badge">${count()}</span>`:''}</a>`).join('');$('#desktop-nav').innerHTML=links;$('#mobile-nav').innerHTML=links;$('#breadcrumb').textContent=nav.find(n=>n[0]===state.route)?.[2]||'Your shopping companion'}
function productCard(p){const d=verdict(p),r=productReviews[p.id],availability=p.availabilityStatus==='out_of_stock'||p.availabilityStatus==='listed_range'?`<p class="availability-warning">${esc(availabilityLabel(p))}</p>`:'';return `<article class="product-card decision-card"><div class="card-top"><span class="retailer retailer-with-logo">${brand(p.retailer,true)}<span>${esc(p.retailer)}<small>${p.species}</small></span></span><button class="icon-button ${state.saved.includes(p.id)?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${state.saved.includes(p.id)}">${icon('bookmark')}</button></div><div class="verdict-pill ${d.tone}">${icon(['meets','likely'].includes(d.key)?'check-circle-2':d.key==='outside'?'circle-x':'info')}${d.label}</div><button class="product-title" data-action="product" data-id="${p.id}">${esc(p.name)}</button><p class="decision-reason">${esc(d.reason)}</p>${evidenceBadge(p)}<div class="tags">${p.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}${p.outdoor===false?'<span class="tag amber">Indoor system</span>':''}</div>${availability}${p.retailer==='Ocado'?'<p class="availability-warning">Edinburgh delivery eligibility unconfirmed</p>':''}<div class="card-bottom"><button class="text-button" data-action="product" data-id="${p.id}">Why & alternatives ${icon('arrow-up-right')}</button><button class="icon-button" data-action="compare-toggle" data-id="${p.id}" aria-label="Compare ${esc(p.name)}" aria-pressed="${state.compare.includes(p.id)}">${icon('columns-2')}</button></div><div class="card-end"><span>Evidence checked ${r?.checked||p.checked}</span><button class="text-button" data-action="add" data-id="${p.id}">${icon('plus')}List</button></div></article>`}
function filtered(ignoreVerdict=false){return products.filter(p=>(state.scope==='all'||Object.hasOwn(retailerReviews,p.retailer))&&(state.retailer==='all'||p.retailer===state.retailer)&&(state.category==='All meat'||p.species===state.category)&&(!state.onlySaved||state.saved.includes(p.id))&&(ignoreVerdict||state.verdict==='all'||verdict(p).key===state.verdict)&&(state.filter==='all'||(state.filter==='organic'&&hasOrganicListing(productReviews[p.id]))||(state.filter==='certifier'&&['code','named'].includes(productReviews[p.id]?.level))||(state.filter==='direct'&&p.farm))&&`${p.name} ${p.retailer} ${p.tags.join(' ')}`.toLowerCase().includes(state.search.toLowerCase()))}
function retailerNote(){if(state.retailer==='all')return '';const items=products.filter(p=>p.retailer===state.retailer),coverage=retailerCoverage(state.retailer,products,productReviews,state),categoryCandidates=items.filter(p=>p.reviewStatus==='category_listing').length,context=retailerResearch.retailers[state.retailer];return `<div class="retailer-guide"><div class="retailer-coverage"><strong>${coverage.matches}</strong><span>confirmed<br>matches</span></div><div><b>${esc(state.retailer)} · ${coverage.matches} confirmed ${coverage.matches===1?'match':'matches'}${coverage.likely?` · ${coverage.likely} pack checks`:''}</b><p>This is not the whole range. ${categoryCandidates?`${categoryCandidates} named items come from a category page. `:''}${coverage.likely?'Pack checks have a retailer organic, free-range or outdoor claim, but are not confirmed until the shelf pack repeats it. ':coverage.matches?'Compare the exact pack before buying. ':'No confirmed match in this catalogue; sourcing candidates and comparisons remain visible. '}Branch stock is unconfirmed.</p>${context?`<button class="text-button" data-action="retailer-research" data-id="${esc(state.retailer)}">Research context ${icon('book-open')}</button>`:''}</div><button class="text-button" data-action="shop-profile">Retailer evidence ${icon('arrow-up-right')}</button></div>`}
function results(){const items=filtered(),base=filtered(true);if(state.sort==='evidence')items.sort((a,b)=>Number(b.identityStatus==='exact_variant')-Number(a.identityStatus==='exact_variant')||a.name.localeCompare(b.name));if(state.sort==='name')items.sort((a,b)=>a.name.localeCompare(b.name));$('#retailer-guide').innerHTML=retailerNote();$('#results-count').textContent=`${items.length} catalogued ${items.length===1?'product':'products'}`;$('#verdict-tabs').innerHTML=Object.entries(verdictNames).map(([key,label])=>`<button class="verdict-tab ${state.verdict===key?'active':''}" data-action="verdict" data-value="${key}" aria-pressed="${state.verdict===key}">${label}<b>${key==='all'?base.length:base.filter(p=>verdict(p).key===key).length}</b></button>`).join('');const groups=state.verdict==='all'?['meets','likely','check','outside','unknown']:[state.verdict];$('#products-grid').innerHTML=items.length?groups.map(key=>{const group=items.filter(p=>verdict(p).key===key);return group.length?`<section class="decision-group"><div class="group-heading"><h3>${verdictNames[key]}</h3><span>${group.length} catalogued</span></div><div class="products-grid">${group.map(productCard).join('')}</div></section>`:''}).join(''):`<div class="empty">${icon('search')}<h2>No catalogue match</h2><p>Try another cut or supermarket. This does not prove that suitable products do not exist.</p><button class="btn" data-action="reset-filters">Reset filters</button></div>`;$('#comparison-tray').innerHTML=state.compare.length?`<span>${state.compare.length} of 3 selected</span><button class="btn primary small" data-action="compare-open">Compare products</button><button class="text-button" data-action="compare-clear">Clear</button>`:'';$('#comparison-tray').hidden=!state.compare.length;icons()}
function discover(){return `<section class="page-heading"><div><p class="eyebrow">BETTER MEAT. YOUR EVERYDAY SHOP.</p><h1>Know what to pick.</h1><p class="subheading">Your supermarket. The exact cut. The evidence behind it.</p></div><a class="btn primary" href="#scan">${icon('scan-line')}Scan a pack</a></section><section class="shopping-hero"><div><span class="small-caps">YOUR SHOPPING STANDARD</span><h2>Properly farmed, with proof.</h2><p>Organic outdoor meat is strongest. Exact free-range or outdoor-bred products can also meet your standard; the product page must say so.</p><button class="standard-chip" data-action="standards">${icon('sliders-horizontal')}Organic first${state.outdoor?' · Outdoor access':''}${state.strict?' · Certificate scope required':''}${icon('chevron-down')}</button></div><div class="hero-facts"><b>${Object.keys(retailerReviews).length}</b><span>major grocers</span><b>${products.filter(p=>Object.hasOwn(retailerReviews,p.retailer)).length}</b><span>catalogued supermarket products</span><small>${catalogueSummary.canonicalVariantCount-catalogueSummary.categoryListingCandidateCount} exact-record reviews · ${catalogueSummary.categoryListingCandidateCount} pack checks<br>Evidence checked 23 Sep 2026</small></div></section><section class="shop-picker"><div class="catalogue-heading"><h2>Where are you shopping?</h2><button class="text-button" data-action="retailer-scores">Compare supermarket coverage ${icon('arrow-up-right')}</button></div><div class="retailer-tiles">${['all',...Object.keys(retailerReviews)].map(r=>`<button class="retailer-tile ${state.retailer===r?'selected':''}" data-action="retailer" data-value="${esc(r)}" aria-pressed="${state.retailer===r}">${r==='all'?`<span class="brand-logo all-shops">${icon('store')}</span>`:brand(r)}<span>${r==='all'?'All shops':esc(r)}</span><small>${r==='all'?'Compare grocers':products.filter(p=>p.retailer===r).length+' catalogued'}</small></button>`).join('')}</div></section><div class="search-row"><label class="search-field">${icon('search')}<input id="product-search" aria-label="Search supermarket meat" placeholder="Search chicken, mince, sirloin…" value="${esc(state.search)}" type="search"></label><select id="source-filter" aria-label="Filter sourcing"><option value="all">All catalogue evidence</option><option value="organic">Organic listings only</option><option value="certifier">Organic + certifier identified</option><option value="direct">Named farms</option></select><select id="scope-filter" aria-label="Shopping directory"><option value="supermarkets">Supermarkets</option><option value="all">Include farms & butchers</option></select><button class="btn ${state.onlySaved?'primary':''}" data-action="saved-only" aria-pressed="${state.onlySaved}">${icon('bookmark')}Saved</button></div><div class="category-tabs">${['All meat','Beef','Lamb','Pork','Chicken'].map(c=>`<button class="chip ${state.category===c?'active':''}" data-action="category" data-category="${c}" aria-pressed="${state.category===c}">${c}</button>`).join('')}</div><div id="retailer-guide"></div><div class="verdict-tabs" id="verdict-tabs" aria-label="Product decisions"></div><div class="score-explainer"><span>${icon('chart-no-axes-combined')}Evidence scores show how much we can substantiate—not how much an animal suffered. Organic evidence earns more points; an exact outdoor claim can still meet your standard.</span><button class="text-button" data-action="score-method">How scoring works</button></div><div class="catalogue-heading"><h2>Your supermarket guide</h2><select id="sort-filter" aria-label="Sort products"><option value="default">Catalogue order</option><option value="score">Highest evidence score</option><option value="name">Product name</option></select><span class="result-count" id="results-count" role="status"></span></div><div id="products-grid"></div><div id="comparison-tray" class="comparison-tray" hidden></div><p class="footer-note">${icon('info')}Verdicts apply to your standard and the exact listing. Missing evidence does not prove poor welfare. Organic is not a guarantee of zero suffering.</p>`}
function render(){
 navigation();
 const views={discover,nearby:nearbyView,suppliers:suppliersView,basket:basketView,scan:scanView};
 $('#main').innerHTML=(views[state.route]||discover)();
 if(state.route==='discover'){
   $('#sort-filter').value=state.sort;$('#sort-filter').addEventListener('change',e=>{state.sort=e.target.value;results()});$('#source-filter').value=state.filter;$('#scope-filter').value=state.scope;results();
   $('#product-search').addEventListener('input',e=>{state.search=e.target.value;results()});
   $('#source-filter').addEventListener('change',e=>{state.filter=e.target.value;if(state.filter==='direct'){state.scope='all';state.retailer='all';render()}else results()});
   $('#scope-filter').addEventListener('change',e=>{state.scope=e.target.value;if(state.scope==='all')state.retailer='all';render()});
 }
 if(state.route==='nearby')$('#store-type').addEventListener('change',e=>{state.storeType=e.target.value;render()});
 if(state.route==='scan')$('#barcode-form').addEventListener('submit',e=>{e.preventDefault();barcodeResult($('#barcode-input').value.trim())});
 icons();decorateBranding();guideLanguage();
}

function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,3000)}
function persist(){try{localStorage.setItem('ff-saved',JSON.stringify(state.saved));localStorage.setItem('ff-basket',JSON.stringify(state.basket));localStorage.setItem('ff-pack-checks',JSON.stringify(state.packChecks));localStorage.setItem('ff-barcode-observations',JSON.stringify(state.barcodeObservations));localStorage.setItem('ff-outdoor',JSON.stringify(state.outdoor));localStorage.setItem('ff-retailer',JSON.stringify(state.retailer));localStorage.setItem('ff-strict',JSON.stringify(state.strict));return true}catch{toast('Storage is unavailable. Keep this tab open to retain your list.');return false}}
function add(id){if(!products.some(p=>p.id===id))throw new Error('Unknown product');state.basket[id]=Math.min(99,(state.basket[id]||0)+1);persist();navigation();if(state.route==='basket')render();icons();toast('Added to your shopping list')}
function dialog(title,body,actions=''){ $('#dialog-content').innerHTML=`<div class="dialog-top"><div><p class="eyebrow">FIELDFARE</p><h2 id="dialog-title">${title}</h2></div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('x')}</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();icons();decorateBranding()}
function packCheckDialog(id){const product=products.find(p=>p.id===id);if(!product)return;const saved=state.packChecks?.[id]||{};dialog(`Check this pack · ${esc(product.name)}`,`<p>Record only what you can see on the pack. This stays on this device and does not change Fieldfare’s evidence score or certification status.</p><form id="pack-check-form" data-id="${esc(id)}"><label>Organic wording seen<input class="field" name="organic" maxlength="120" value="${esc(saved.organic||'')}" placeholder="e.g. Organic"></label><label>Control body / code<input class="field" name="control" maxlength="120" value="${esc(saved.control||'')}" placeholder="e.g. GB-ORG-05"></label><label>Outdoor / free-range wording<input class="field" name="rearing" maxlength="160" value="${esc(saved.rearing||'')}" placeholder="Copy the pack wording"></label><label>Pack size or use-by date<input class="field" name="pack" maxlength="120" value="${esc(saved.pack||'')}" placeholder="Optional"></label><label>Notes<input class="field" name="notes" maxlength="300" value="${esc(saved.notes||'')}" placeholder="Optional, avoid personal details"></label></form><p class="method-note">A pack observation can reveal a mismatch. It cannot prove farm conditions, current certification scope or stock at another branch.</p>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="save-pack-check" data-id="${esc(id)}">Save pack check</button>`)}
function evidenceSources(sources){return sources.map(x=>`<a class="source-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${icon('external-link')}${esc(x.label)}</a>`).join('')}
function productDetail(id){const p=products.find(p=>p.id===id);if(!p)return;const r=productReviews[id];const organic=hasOrganicListing(r);const d=verdict(p);dialog(`${brand(p.retailer,true)}${esc(p.name)}`,`<div class="decision-banner ${d.tone}"><b>${d.label}</b><p>${esc(d.reason)}</p></div>${p.availability==='unavailable'?'<p class="availability-warning">Retailer listing showed unavailable when reviewed; local availability unconfirmed.</p>':''}${scorePanel(p)}${swapPanel(p)}`+`<p>${esc(p.retailer)} · ${p.species}</p><div class="evidence-verdict ${organic?'':'unconfirmed'}"><span class="small-caps">ORGANIC CHECK</span><h3>${esc(organicEvidenceLabel(r))}</h3><p>${esc(r.summary)}</p></div><h3 class="evidence-title">What the evidence supports</h3><p>${esc(r.why)}</p><div class="check-row"><b>Organic claim applies to</b><span>${esc(r.scope)}</span></div><div class="check-row"><b>Named organic certifier</b><span>${esc(r.certifier||'Not established from reviewed sources')}</span></div><div class="check-row"><b>Code on reviewed listing</b><span>${esc(r.code||'Not found in reviewed listing')}</span></div><div class="check-row"><b>Current operator certificate</b><span>${esc(r.certificate||'Not independently retrieved')}</span></div>${r.operatorDirectory?`<div class="pack-check"><b>Independent operator-directory check</b><p>${esc(r.operatorDirectory)}</p><p>Directory status does not establish the trading schedule for this exact product.</p></div>`:''}<div class="check-row"><b>Named farm / exact batch</b><span>${p.farm?esc(p.farm)+' · batch not matched':'Not established'}</span></div>${p.directory?'<p class="method-note">Pasture for Life directory evidence concerns pasture feeding. It does not independently establish organic certification.</p>':''}<h3 class="evidence-title">What still needs checking</h3><p>${esc(r.limits)}</p><div class="pack-check"><b>At the shelf</b><p>${organic?'Match this exact product and organic wording. Find the certifier code and agricultural origin on the pack. If they do not match the evidence, do not treat this entry as confirmation.':'This product does not qualify for the organic filter. Free-range, RSPCA Assured, grass-fed and premium branding do not establish organic certification.'}</p></div>${p.outdoor===false&&state.outdoor?'<p class="method-note">This indoor system is outside your outdoor-access preference.</p>':''}<h3 class="evidence-title">Sources behind this decision</h3>${evidenceSources(r.sources)}${organic?evidenceSources([{label:'UK organic control bodies — checks certifier identity, not this batch',url:organicSources.controlBodies},{label:'What an organic label must show',url:organicSources.labelling}]):''}<p class="method-note">Reviewed ${p.checked}. An official product listing is evidence of the seller’s claim; it is not a fresh audit of the farm. Organic standards do not guarantee that an individual animal never suffered.</p>`,`<a class="btn" href="${p.url}" target="_blank" rel="noopener noreferrer">Visit retailer ${icon('arrow-up-right')}</a><button class="btn primary" data-action="add" data-id="${p.id}">${icon('plus')}Add to list</button>`)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(a==='close')$('#detail-dialog').close();if(a==='product')productDetail(id);if(a==='add')add(id);if(a==='save'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render()}if(a==='category'){state.category=el.dataset.category;render()}if(a==='saved-only'){state.onlySaved=!state.onlySaved;render()}if(a==='reset-filters'){state.category='All meat';state.search='';state.retailer='all';state.filter='all';state.onlySaved=false;state.verdict='all';state.scope='supermarkets';persist();render()}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='check-pack')packCheckDialog(el.dataset.id);if(el.dataset.action==='save-pack-check'){const form=$('#pack-check-form');if(!form)return;const values=Object.fromEntries(new FormData(form).entries());state.packChecks[el.dataset.id]={...values,checkedAt:new Date().toISOString()};persist();$('#detail-dialog').close();toast('Pack check saved on this device')}});
window.addEventListener('hashchange',()=>{stopCamera();if($('#detail-dialog').open)$('#detail-dialog').close();state.route=location.hash.slice(1)||'discover';if(!nav.some(n=>n[0]===state.route))state.route='discover';render();window.scrollTo(0,0)});
function heading(eyebrow,title,subtitle,action=''){return `<section class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subheading">${subtitle}</p></div>${action}</section>`}
function nearbyView(){let list=stores.filter(s=>state.storeType==='All'||s.type===state.storeType);if(state.origin)list=[...list].sort((a,b)=>(coordinates[a.postcode]?miles(state.origin,coordinates[a.postcode]):Infinity)-(coordinates[b.postcode]?miles(state.origin,coordinates[b.postcode]):Infinity));return `${heading('EDINBURGH & AROUND','Find your next stop.','Real shops and collection points. Check stock before setting off.',`<button class="btn" data-action="location">${icon('locate-fixed')}Set starting point</button>`)}<div class="search-row"><button class="btn" data-action="location">${icon('map-pin')}${state.origin?esc(state.origin.label):'Set postcode or use location'}</button><select id="store-type" aria-label="Type of shop">${['All','Supermarket','Farm','Butcher'].map(t=>`<option ${t===state.storeType?'selected':''}>${t}</option>`).join('')}</select>${state.origin?'<button class="text-button" data-action="clear-location">Clear location</button>':''}</div>${state.origin?'<p class="method-note">Approximate straight-line distances to postcode centres. These are not driving or walking distances.</p>':''}<div class="list-stack">${list.map(s=>{const n=products.filter(p=>p.retailer===s.retailer&&(!state.outdoor||p.outdoor)).length;return `<article class="location-card"><span class="species-icon">${icon(s.type==='Farm'?'tractor':s.type==='Butcher'?'store':'shopping-bag')}</span><div class="location-info"><div class="small-caps">${s.type}${state.origin&&coordinates[s.postcode]?` · ${miles(state.origin,coordinates[s.postcode]).toFixed(1)} miles approx.`:''}</div><h3>${s.type==='Supermarket'&&brandLogos[s.retailer]?brand(s.retailer,true):''}${esc(s.name)}</h3><p>${esc(s.address)} · ${s.postcode}</p><p>${esc(s.note)}${n?` · ${n} catalogue ${n===1?'candidate':'candidates'}`:''}</p></div><div class="store-actions"><a class="btn small" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.name+' '+s.address+' '+s.postcode)}" target="_blank" rel="noopener noreferrer">${icon('navigation')}Directions</a><a class="btn small" href="${s.url}" target="_blank" rel="noopener noreferrer">Store info ${icon('arrow-up-right')}</a></div></article>`}).join('')}</div><p class="footer-note">${icon('info')}Catalogue counts describe the retailer’s listed products, not stock at this branch. Coordinates: Postcodes.io / ONS postcode data.</p>`}
function suppliersView(){return `${heading('KNOW WHO’S BEHIND IT','Know where to shop.','Eleven major grocers reviewed, alongside farms and butchers. Open a profile for the organic evidence.')}<div class="supplier-grid">${suppliers.map(s=>`<article class="supplier-card"><div class="card-top">${brandLogos[s.name]?brand(s.name):`<span class="supplier-initials">${s.initials}</span>`}<span class="tag">${s.type}</span></div><div class="small-caps">${esc(s.area)}</div><h3>${esc(s.name)}</h3><p>${esc(s.desc)}</p><div class="product-evidence">${icon(s.evidence.includes('match')?'badge-check':'file-text')}${retailerReviews[s.name]?(products.some(p=>p.retailer===s.name&&hasOrganicListing(productReviews[p.id]))?'Organic product evidence found':'No organic match in reviewed catalogue'):s.evidence}</div><div class="card-bottom"><span class="result-count">${esc(s.access)}</span><button class="text-button" data-action="supplier" data-id="${s.id}">View profile ${icon('arrow-up-right')}</button></div></article>`).join('')}</div><p class="footer-note">${icon('info')}A certified farm can also sell bought-in meat. Always match the evidence to your chosen product.</p>`}
function supplierDetail(id){const s=suppliers.find(s=>s.id===id);if(!s)return;dialog(`${brandLogos[s.name]?brand(s.name,true):''}${esc(s.name)}`,`<p>${esc(s.area)} · ${s.type}</p><p>${esc(s.desc)}</p>${retailerReviews[s.name]?`<div class="evidence-verdict"><h3>Organic meat review</h3><p>${esc(retailerReviews[s.name].verdict)}</p><p>${esc(retailerReviews[s.name].limit)}</p></div><h3 class="evidence-title">Sources checked</h3>${evidenceSources(retailerReviews[s.name].sources)}`:''}<div class="note-box"><b>${s.evidence}</b><p>${esc(s.note)}</p></div><div class="check-row"><b>How to shop</b><span>${esc(s.access)}</span></div><a class="source-link" href="${s.source}" target="_blank" rel="noopener noreferrer">${icon('external-link')}Read sourcing / collection evidence</a>${s.products.length?`<h3 style="margin-top:24px">In your catalogue</h3>${s.products.map(id=>{const p=products.find(p=>p.id===id);return `<button class="btn wide" data-action="product" data-id="${id}">${esc(p.name)} · ${esc(organicEvidenceLabel(productReviews[p.id]))} ${icon('arrow-right')}</button>`}).join('')}`:'<p class="method-note">No qualifying organic meat cut was established in this review. This is an evidence gap, not a claim that suitable products never exist. Ask for the exact product and certification.</p>'}`,`<a class="btn primary" href="${s.url}" target="_blank" rel="noopener noreferrer">Visit supplier ${icon('arrow-up-right')}</a>`)}
function basketView(){const items=products.filter(p=>state.basket[p.id]);if(!items.length)return `${heading('YOUR NEXT SHOP','A considered basket.','Keep your chosen cuts together, ready for your next shop.')}<div class="empty">${icon('shopping-basket')}<h2>Make a good start.</h2><p>Add meat from the catalogue to build your shopping list. Your choices stay on this device.</p><a class="btn primary" href="#discover">Explore the catalogue ${icon('arrow-right')}</a></div>`;const shops=[...new Set(items.map(p=>p.retailer))];return `${heading('YOUR NEXT SHOP','A considered basket.','A shopping list, not an order. Check the sourcing and current pack before buying.',`<button class="btn" data-action="export">${icon('download')}Export list</button>`)}<div class="basket-layout"><div class="list-stack">${items.map(p=>`<article class="basket-item"><span class="species-icon">${icon(speciesIcon(p.species))}</span><div class="item-info"><p>${esc(p.retailer)}</p><h3><button class="text-button" data-action="product" data-id="${p.id}">${esc(p.name)}</button></h3><span class="verdict-pill ${verdict(p).tone}">${verdict(p).label}</span></div><div class="quantity"><button data-action="decrease" data-id="${p.id}" aria-label="Decrease quantity of ${esc(p.name)}">${icon('minus')}</button><span aria-label="Quantity">${state.basket[p.id]}</span><button data-action="increase" data-id="${p.id}" aria-label="Increase quantity of ${esc(p.name)}">${icon('plus')}</button></div><button class="icon-button" data-action="remove" data-id="${p.id}" aria-label="Remove ${esc(p.name)}">${icon('trash-2')}</button></article>`).join('')}</div><aside class="summary-panel"><h3>Your shop, at a glance.</h3><div class="summary-row"><span>Items on your list</span><b>${count()}</b></div><div class="summary-row"><span>Suppliers / retailers</span><b>${shops.length}</b></div><p style="margin-top:18px">Every item is a sourcing candidate. The list does not confirm stock, a purchase, or a welfare audit.</p><button class="btn primary wide" data-action="basket-stores">${icon('map-pin')}Find buying options</button><button class="btn wide" data-action="export">${icon('download')}Export your list</button></aside></div>`}
function basketStores(){const items=products.filter(p=>state.basket[p.id]);const names=[...new Set(items.map(p=>p.retailer))];dialog('Where to buy your list',`${names.map(name=>{const p=items.find(p=>p.retailer===name),n=items.filter(p=>p.retailer===name).length;return `<div class="check-row"><b>${esc(name)}<br><span>${n} different ${n===1?'item':'items'}</span></b><a class="text-button" href="${p.url}" target="_blank" rel="noopener noreferrer">Check / preorder ${icon('arrow-up-right')}</a></div>`}).join('')}<p class="method-note">Links open the relevant supplier or product page. No retailer inventory or checkout is connected.</p>`,`<a href="#nearby" class="btn primary">See Edinburgh shops ${icon('map-pin')}</a>`)}
function scanView(){return `${heading('IN THE AISLE','Know what you’re holding.','Read a barcode, then check the source. A barcode alone cannot verify welfare.')}<div class="scan-layout"><section class="scan-surface">${icon('scan-barcode')}<h2>A closer look, in seconds.</h2><p>Use your camera or a pack photo to read the product’s barcode.</p><button class="btn" data-action="camera">${icon('camera')}Open scanner</button><button class="text-button" style="color:#dae5cb;margin-top:18px" data-action="photo">${icon('image')}Read a barcode photo</button><input id="barcode-photo" type="file" accept="image/*" hidden></section><section class="scan-help"><h2>Have the number instead?</h2><p>Enter the digits printed below the barcode.</p><form id="barcode-form"><input id="barcode-input" class="field" inputmode="numeric" autocomplete="off" placeholder="EAN / UPC number" aria-label="Barcode number" maxlength="14" required><button class="btn primary" type="submit">Check</button></form><div class="mini-step"><span>1</span><div><b>Identify the product</b><p>Read the code without guessing a farm or source.</p></div></div><div class="mini-step"><span>2</span><div><b>Check the evidence</b><p>This first catalogue has no independently verified barcode links yet. Unmatched codes stay unverified.</p></div></div><div class="mini-step"><span>3</span><div><b>Find a better-documented cut</b><p>Search the catalogue for the meat and retailer on your pack.</p></div></div></section></div>`}
function barcodeResult(code){stopCamera();if(!validBarcode(code)){dialog('Check those digits',`<p>The barcode should contain 8, 12, 13 or 14 digits and a valid check digit. Try entering it again or use a clearer photo.</p>`,`<button class="btn primary" data-action="close">Try again</button>`);return}dialog('No reviewed barcode match',`<p class="eyebrow">BARCODE ${esc(code)}</p><div class="note-box"><b>Sourcing not verified</b><p>This barcode is not linked to a reviewed Fieldfare product. It has not been scored or approved.</p></div><p>Record the wording from this pack to create a private review record, then use it to compare future supermarket evidence. Open Food Facts can help identify a product, but is not welfare evidence.</p><a class="source-link" href="https://world.openfoodfacts.org/product/${code}" target="_blank" rel="noopener noreferrer">${icon('external-link')}Look up product identity on Open Food Facts</a>`,`<button class="btn" data-action="record-barcode" data-code="${esc(code)}">${icon('clipboard-pen-line')}Record this pack</button><a class="btn primary" href="#discover">Search meat catalogue ${icon('search')}</a>`)}
function barcodeObservationDialog(code=''){const retail=Object.keys(retailerReviews).sort();dialog('Record an unreviewed pack',`<p>Capture the details visible on the product you are holding. This creates a private, device-local review record; it does not approve the product or upload anything.</p><form id="barcode-observation-form"><label>Barcode<input class="field" name="barcode" inputmode="numeric" maxlength="14" value="${esc(code)}" placeholder="EAN / UPC if shown"></label><label>Supermarket<select class="field" name="retailer"><option value="">Choose a supermarket</option>${retail.map(name=>`<option>${esc(name)}</option>`).join('')}</select></label><label>Exact pack name<input class="field" name="name" maxlength="180" required placeholder="Copy the front of pack"></label><label>Meat type<select class="field" name="species"><option value="">Choose type</option>${['Chicken','Turkey','Pork','Beef','Lamb','Other meat'].map(name=>`<option>${name}</option>`).join('')}</select></label><label>Organic / control code<input class="field" name="organic" maxlength="140" placeholder="Copy wording or code if visible"></label><label>Outdoor / welfare wording<input class="field" name="rearing" maxlength="180" placeholder="Free range, outdoor bred, RSPCA Assured…"></label><label>Pack size and shop / postcode<input class="field" name="location" maxlength="160" placeholder="e.g. 400g · Tesco Leith Walk"></label><label>Notes<input class="field" name="notes" maxlength="300" placeholder="Optional; avoid personal details"></label></form><p class="method-note">Photographs are not stored in this first local version. Retain them yourself if you later want to submit a review. A barcode identifies a trade item; it does not establish farming conditions.</p>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="save-barcode-observation">Save local record</button>`)}
function observationsDialog(){const observations=[...state.barcodeObservations].reverse();dialog('Your local pack observations',observations.length?`<p>These records are private to this device and never change product verdicts. Export them when you want to retain or share your review notes.</p><div class="retailer-score-list">${observations.map(x=>`<div class="check-row"><b>${esc(x.name||'Unnamed pack')}<br><small>${esc(x.retailer||'Retailer not recorded')} · ${esc(x.barcode||'No barcode')} · ${new Date(x.recordedAt).toLocaleDateString('en-GB')}</small></b><span>${esc(x.species||'Type not recorded')}</span></div>`).join('')}</div>`:`<p>No pack observations saved on this device yet.</p>`,`<button class="btn" data-action="close">Close</button>${observations.length?'<button class="btn primary" data-action="export-observations">Export observations</button>':''}`)}
function exportObservations(){const data={app:'Fieldfare',type:'pack-observations',exported:new Date().toISOString(),records:state.barcodeObservations};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fieldfare-pack-observations.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Pack observations exported')}
const showUnreviewedBarcode=barcodeResult;
barcodeResult=function(code){
 stopCamera();
 if(!validBarcode(code)){showUnreviewedBarcode(code);return}
 const reviewed=lookupReviewedBarcode(code);
 if(!reviewed){showUnreviewedBarcode(code);return}
 const d=verdict(reviewed);
 dialog('Reviewed pack match',`<p class="eyebrow">BARCODE ${esc(code)}</p><div class="decision-banner ${d.tone}"><b>${esc(reviewed.name)}</b><p>${esc(d.reason)}</p></div><p>This mapping was verified against the reviewed pack record. Check the pack name, weight and date before relying on it.</p>`,`<button class="btn primary" data-action="product" data-id="${reviewed.id}">Open product evidence</button>`);
};
let cameraControls=null,cameraCancelled=false,scannerPromise=null;
function loadScanner(){if(window.ZXingBrowser)return Promise.resolve(window.ZXingBrowser);if(!scannerPromise)scannerPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='./assets/zxing.min.js';s.onload=()=>resolve(window.ZXingBrowser);s.onerror=()=>{scannerPromise=null;s.remove();reject(new Error('Scanner could not load'))};document.head.appendChild(s)});return scannerPromise}
function stopCamera(){cameraCancelled=true;cameraControls?.stop();cameraControls=null;const video=$('#camera-video');video?.srcObject?.getTracks().forEach(t=>t.stop());if(video)video.srcObject=null}
async function startCamera(){cameraCancelled=false;dialog('Scan the pack',`<video id="camera-video" class="camera-video" muted playsinline></video><p id="camera-status" role="status">Starting camera…</p><p>Point at the barcode in good light. Camera images stay on your device.</p>`);try{const zxing=await loadScanner();if(cameraCancelled)return;const reader=new zxing.BrowserMultiFormatReader();const controls=await reader.decodeFromConstraints({video:{facingMode:{ideal:'environment'}},audio:false},$('#camera-video'),(result)=>{if(result&&!cameraCancelled)barcodeResult(result.getText())});if(cameraCancelled){controls.stop();return}cameraControls=controls;$('#camera-status').textContent='Camera ready — keep the barcode steady.'}catch(error){if(cameraCancelled)return;$('#camera-status').textContent='Camera unavailable. Allow camera access in your browser, or enter the number / choose a photo.';$('#camera-status').className='error'}}
async function scanPhoto(file){if(!file)return;dialog('Reading your photo',`<p role="status">Looking for a barcode. The image stays on your device.</p>`);const url=URL.createObjectURL(file);try{const z=await loadScanner();const result=await new z.BrowserMultiFormatReader().decodeFromImageUrl(url);barcodeResult(result.getText())}catch{dialog('No barcode found',`<p>Try a close, sharp photo of the complete barcode, or enter the printed digits. Nothing has been uploaded.</p>`,`<button class="btn primary" data-action="close">Try another way</button>`)}finally{URL.revokeObjectURL(url)}}
let coordinates={};
fetch('./locations.json').then(r=>r.json()).then(data=>{coordinates=data;if(state.route==='nearby')render()}).catch(()=>{});
function locationDialog(){dialog('Your starting point',`<p>Choose a postcode for approximate distances, or use your current location. This is only used for this session.</p><form id="postcode-form"><label for="postcode-input">UK postcode</label><input class="field" id="postcode-input" autocomplete="postal-code" placeholder="For example, EH1 3RZ" maxlength="10" required><p style="font-size:12px;margin:9px 0">A postcode you submit is sent to Postcodes.io to find its centre.</p><button class="btn primary" type="submit">Find nearby shops</button></form><p id="location-error" role="status"></p><div class="check-row"><b>Or use your device</b><button class="text-button" data-action="geolocate">${icon('locate-fixed')}Use my location</button></div><p class="method-note">Device coordinates stay in this tab. There is no background tracking.</p>`);$('#postcode-form').addEventListener('submit',async e=>{e.preventDefault();const code=$('#postcode-input').value.trim();const error=$('#location-error');if(!/^[A-Za-z]{1,2}\d[A-Za-z\d]?\s*\d[A-Za-z]{2}$/.test(code)){error.textContent='Enter a complete UK postcode.';error.className='error';return}const button=e.target.querySelector('button');button.disabled=true;error.textContent='Looking up your postcode…';try{const r=await fetch('https://api.postcodes.io/postcodes/'+encodeURIComponent(code),{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error();const {result}=await r.json();setOrigin({latitude:result.latitude,longitude:result.longitude,label:result.postcode})}catch{error.textContent='Postcode not found or connection unavailable. Try again, or browse the Edinburgh list.';error.className='error'}finally{button.disabled=false}})}
function setOrigin(origin){state.origin=origin;$('#location-label').textContent=origin.label;$('#detail-dialog').close();if(state.route!=='nearby')location.hash='nearby';else render()}
function geolocate(){const status=$('#location-error');if(!navigator.geolocation){status.textContent='Location is not supported here. Use a postcode instead.';return}status.textContent='Waiting for location permission…';navigator.geolocation.getCurrentPosition(p=>setOrigin({latitude:p.coords.latitude,longitude:p.coords.longitude,label:'Current location'}),()=>{status.textContent='Location unavailable. Use a postcode or browse without distances.';status.className='error'},{enableHighAccuracy:false,timeout:10000,maximumAge:120000})}
function standardsDialog(){dialog('Your sourcing standards',`<p>Focus on properly farmed meat, with visible evidence for the product you actually buy.</p><div class="check-row"><b>Direct match</b><span>Organic outdoor meat, or an exact free-range / outdoor-bred product listing</span></div><div class="check-row"><b>Pack check needed</b><span>Credible official organic or outdoor claim; confirm it on the shelf pack</span></div><p class="method-note">The asterisk is deliberate: it is a reasonable presumption from a retailer’s claim, never proof of a farm audit, current stock or a specific batch.</p><label class="toggle-row"><input type="checkbox" id="outdoor-toggle" ${state.outdoor?'checked':''}><div>Require outdoor-access evidence<span>Known indoor products stay visible as comparisons and cannot meet this preference. Outdoor claims still need product-level verification.</span></div></label><label class="toggle-row"><input type="checkbox" id="strict-toggle" ${state.strict?'checked':''}><div>Require independently checked certificate scope<span>Stricter than a retailer listing. No current catalogue product has this full scope check yet.</span></div></label><div class="check-row"><b>Recommendations</b><span>Meat only</span></div><div class="check-row"><b>Unknown sourcing</b><span>Never automatically approved</span></div><div class="check-row"><b>Preferred area</b><span>Edinburgh and around</span></div><h3>What to look for on the pack</h3><div class="check-row"><b>Strongest signals</b><span>Organic mark plus control code, or clear free-range / outdoor wording.</span></div><div class="check-row"><b>Useful welfare detail</b><span>RSPCA Assured, BCC tier, stocking density, slower-growing breed and range-access wording.</span></div><div class="check-row"><b>Do not overread</b><span>British, premium, corn-fed, grass-fed or Red Tractor alone do not establish outdoor access.</span></div><p class="method-note">Certification helps assess farming standards. It cannot prove that an individual animal never suffered. Winter shelter is not automatically poor welfare.</p>`,`<button class="btn primary" data-action="save-standards">Save standards</button>`)}
function retailerResearchDialog(name){const entry=retailerResearch.retailers[name],base=retailerResearch.framework;if(!entry){dialog('Research basis',`<p>${esc(base.summary)}</p><h3 class="evidence-title">Sources reviewed</h3>${evidenceSources(base.sources)}`);return}dialog(`${esc(name)} research context`,`<p>${esc(entry.summary)}</p><div class="note-box"><b>Scope of this research</b><p>It informs where to look. It does not change a product verdict or confirm a particular pack.</p></div><h3 class="evidence-title">What the sources say</h3>${entry.points.map(point=>`<div class="check-row"><span style="text-align:left">${esc(point)}</span></div>`).join('')}<h3 class="evidence-title">Sources reviewed</h3>${evidenceSources(entry.sources)}<p class="method-note">Research checked ${retailerResearch.checked}. Company reports may describe their own supply chain; independent reports assess stated policy and disclosed performance. Neither is an audit of the pack in your hand.</p>`)}
function publishedRankingsDialog(){const {wwf,bbfaw,checked}=publishedRetailerRankings,wwfRows=Object.entries(wwf.scores).sort((a,b)=>b[1]-a[1]),bbfawRows=Object.entries(bbfaw.ratings).sort((a,b)=>a[1].localeCompare(b[1]));dialog('Published retailer research rankings',`<p>These external retailer measures sit beside Fieldfare’s pack-by-pack guide. They never change a product verdict.</p><h3 class="evidence-title">${esc(wwf.title)}</h3><p>${esc(wwf.summary)}</p><div class="retailer-score-list">${wwfRows.map(([name,score],index)=>`<button class="retailer-score-row" data-action="score-shop" data-value="${esc(name)}">${brand(name)}<span><b>${index+1}. ${esc(name)}</b><small>WWF Basket reported</small></span><strong>${score}%</strong>${icon('arrow-right')}</button>`).join('')}</div><a class="source-link" href="${wwf.source.url}" target="_blank" rel="noopener noreferrer">${icon('external-link')}${esc(wwf.source.label)}</a><h3 class="evidence-title" style="margin-top:26px">${esc(bbfaw.title)}</h3><p>${esc(bbfaw.summary)}</p><div class="retailer-score-list">${bbfawRows.map(([name,rating])=>`<button class="retailer-score-row" data-action="score-shop" data-value="${esc(name)}">${brand(name)}<span><b>${esc(name)}</b><small>BBFAW corporate impact rating</small></span><strong>${esc(rating)}</strong>${icon('arrow-right')}</button>`).join('')}</div><a class="source-link" href="${bbfaw.source.url}" target="_blank" rel="noopener noreferrer">${icon('external-link')}${esc(bbfaw.source.label)}</a><p class="method-note">Published reporting checked ${checked}. WWF’s percentage ranks broader food-system reporting. BBFAW’s letters assess corporate disclosure and reported impact. Neither tells you whether a specific product meets your outdoor or organic standard.</p>`)}
function aboutDialog(){dialog('Evidence, without guesswork',`<p>Organic is checked separately from free-range, welfare assurance and pasture feeding. Each product now explains its inclusion and links to the evidence.</p><div class="check-row"><b>Control code listed</b><span>Code seen on product page; certifier identity checked</span></div><div class="check-row"><b>Certifier named</b><span>Seller names a body; code or operator schedule still missing</span></div><div class="check-row"><b>Organic product listing</b><span>Exact product says organic; certifier details not established</span></div><p class="method-note">The shopping guide separates matches, pack checks, preference mismatches and unknown evidence. The organic filter includes explicit product listings. The stricter certifier filter requires a named organic certifier or control code. Neither claims a current operator certificate or pack-level audit. Supplier-wide claims are excluded from both.</p><div class="check-row"><b>Product listing</b><span>The seller describes the sourcing</span></div><div class="check-row"><b>Directory match</b><span>The farm appears in a certifier’s directory</span></div><div class="check-row"><b>Current product / batch</b><span>Still requires a purchase-time check</span></div><p style="margin-top:20px">These are evidence levels, not a numerical measure of animal suffering. We do not give a retailer’s entire range the status of its best product.</p><p>Research checked 22 September 2026. Availability and prices are not live. The pasture image is an original illustrative image, not a photograph of a listed supplier.</p><a class="source-link" href="${SOURCES.pfl}" target="_blank" rel="noopener noreferrer">Pasture for Life directory ${icon('external-link')}</a><a class="source-link" href="${SOURCES.organic}" target="_blank" rel="noopener noreferrer">Approved UK organic control bodies ${icon('external-link')}</a><p class="method-note">Retailer logos identify their brands. Fieldfare is independent and is not endorsed by these retailers.</p><p class="method-note">No advertising trackers or account required for your list. Saved products, your basket and preferences stay in this browser; the hosting service may require sign-in to open the app. Directions and supplier links open external services.</p>`)}
function catalogueAuditDialog(){const retailers=Object.keys(retailerReviews).sort();const species=['Chicken','Pork','Beef','Lamb'];const rows=retailers.map(name=>{const listed=products.filter(p=>p.retailer===name),exact=listed.filter(p=>p.reviewStatus==='reviewed'),candidates=listed.length-exact.length,matching=exact.filter(p=>['meets','likely'].includes(decision(p,productReviews[p.id],state).key)).length;const detail=species.map(kind=>{const total=listed.filter(p=>p.species===kind).length,reviewed=exact.filter(p=>p.species===kind).length;return total?`${kind} ${reviewed}/${total}`:''}).filter(Boolean).join(' · ');return `<button class="retailer-score-row" data-action="score-shop" data-value="${esc(name)}">${brand(name)}<span><b>${esc(name)}</b><small>${exact.length} exact-record reviews · ${candidates} pack candidates<br>${esc(detail)}</small></span><strong>${matching}</strong>${icon('arrow-right')}</button>`}).join('');dialog('Catalogue coverage & audit',`<p>Fieldfare has ${catalogueSummary.canonicalVariantCount} catalogue variants, but only ${catalogueSummary.canonicalVariantCount-catalogueSummary.categoryListingCandidateCount} have an exact-record review. The rest are named category candidates that need the actual shelf pack or product listing checked.</p><div class="note-box"><b>How to read this</b><p>The number on the right is the count of exact-record products currently matching your standards, including conditional pack checks. It is not a retailer-wide welfare score and does not estimate stock.</p></div><div class="retailer-score-list">${rows}</div><h3 class="evidence-title">Next audit order</h3><div class="check-row"><b>1. Chicken and pork</b><span>Highest impact and the clearest welfare-label differences.</span></div><div class="check-row"><b>2. Tesco, Sainsbury’s, Waitrose, M&S</b><span>Large named ranges with enough official material to verify exact claims.</span></div><div class="check-row"><b>3. Aldi, Lidl, Co-op, Morrisons, Iceland</b><span>Confirm range-specific labels rather than inferring from a supermarket policy.</span></div><p class="method-note">Selecting a retailer opens its catalogue. Every category candidate remains a pack check until its own source is reviewed.</p>`)}
let installPrompt=null,swRegistration=null,offlineReady=false;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
window.addEventListener('appinstalled',()=>{installPrompt=null;toast('Fieldfare is installed')});
async function install(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;return}dialog('Fieldfare, on your home screen',`<p>Install the app for quick access and a quieter, full-screen experience.</p><div class="check-row"><b>iPhone / iPad · Safari</b><span>Share → Add to Home Screen</span></div><div class="check-row"><b>Android · Chrome</b><span>Browser menu → Install app</span></div><div class="check-row"><b>Desktop · Chrome or Edge</b><span>Use the install icon in the address bar</span></div><p class="method-note">If you are viewing this inside another app, open the site in your regular browser first. The catalogue and your list work offline after the first complete visit; supplier links and postcode lookup need a connection.</p>`)}
function exportData(){const data={app:'Fieldfare',version:2,exported:new Date().toISOString(),saved:state.saved,basket:products.filter(p=>state.basket[p.id]).map(p=>({id:p.id,name:p.name,supplier:p.retailer,quantity:state.basket[p.id],source:p.url})),packObservations:state.barcodeObservations,preferences:{outdoorAccess:state.outdoor,strictCertificate:state.strict,retailer:state.retailer,organic:true,meatOnly:true}};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fieldfare-shopping-list.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your list has been exported')}
function settingsDialog(){dialog('Make yourself at home',`<div class="check-row"><b>Storage</b><span>This device only</span></div><div class="check-row"><b>Offline catalogue</b><span id="offline-readiness">${offlineReady?'Ready on this device':'Preparing — connect and revisit'}</span></div><div class="check-row"><b>Research date</b><span>22 September 2026</span></div><p style="margin-top:18px">Your basket and saved items are stored in this browser. They are not synced to other devices. Clearing browser data will remove them.</p><div class="two-buttons"><button class="btn" data-action="install">${icon('download')}Install app</button><button class="btn" data-action="export">Export list</button><button class="btn" data-action="standards">Your standards</button></div>${swRegistration?.waiting?'<button class="btn primary wide" data-action="update-app">Update available — refresh app</button>':''}<p class="method-note">App assets are cached for offline use. External stock checks, maps and supplier websites need an internet connection.</p><button class="text-button" style="color:var(--red)" data-action="reset-dialog">Clear saved data on this device</button>`)}
function checkOffline(){const worker=navigator.serviceWorker?.controller||swRegistration?.active;if(!worker)return;const channel=new MessageChannel();channel.port1.onmessage=e=>{offlineReady=!!e.data.ready;if($('#offline-readiness'))$('#offline-readiness').textContent=offlineReady?'Ready on this device':'Still preparing';channel.port1.close()};worker.postMessage({type:'CACHE_STATUS'},[channel.port2])}
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(reg=>{swRegistration=reg;navigator.serviceWorker.ready.then(()=>checkOffline());reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',()=>{if(reg.waiting&&navigator.serviceWorker.controller)toast('An app update is ready. Open settings to refresh.')})})}).catch(()=>{offlineReady=false});
navigator.serviceWorker?.addEventListener('controllerchange',()=>checkOffline());
function connection(){const b=$('#connection-banner');b.hidden=navigator.onLine;b.textContent='You’re offline. Your catalogue and saved list are available; external services will need a connection.'}
window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
$('#detail-dialog').addEventListener('close',stopCamera);
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(a==='supplier')supplierDetail(id);if(a==='standards')standardsDialog();if(a==='about')aboutDialog();if(a==='retailer-research')retailerResearchDialog(id);if(a==='location')locationDialog();if(a==='geolocate')geolocate();if(a==='clear-location'){state.origin=null;$('#location-label').textContent='Edinburgh';render()}if(a==='settings')settingsDialog();if(a==='install')install();if(a==='export')exportData();if(a==='basket-stores')basketStores();if(a==='camera')startCamera();if(a==='photo')$('#barcode-photo').click();if(a==='save-standards'){state.outdoor=$('#outdoor-toggle').checked;state.strict=$('#strict-toggle').checked;persist();$('#detail-dialog').close();render();toast('Your standards are saved')}if(['increase','decrease','remove'].includes(a)){if(a==='increase')state.basket[id]=Math.min(99,(state.basket[id]||0)+1);if(a==='decrease'){state.basket[id]--;if(state.basket[id]<=0)delete state.basket[id]}if(a==='remove')delete state.basket[id];persist();render()}if(a==='update-app'){swRegistration?.waiting?.postMessage({type:'SKIP_WAITING'});navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true})}if(a==='reset-dialog')dialog('Clear your saved data?',`<p>This removes your Fieldfare basket, saved products and sourcing preference from this device. Export your list first if you want to keep it.</p>`,`<button class="btn" data-action="close">Keep my data</button><button class="btn danger" data-action="reset-confirm">Clear my data</button>`);if(a==='reset-confirm'){state.basket={};state.saved=[];state.outdoor=true;state.strict=false;state.retailer='all';persist();$('#detail-dialog').close();render();toast('Saved data cleared')}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="published-rankings"]'))publishedRankingsDialog();if(e.target.closest('[data-action="catalogue-audit"]'))catalogueAuditDialog()});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='record-barcode')barcodeObservationDialog(el.dataset.code||'');if(el.dataset.action==='view-observations')observationsDialog();if(el.dataset.action==='export-observations')exportObservations();if(el.dataset.action==='save-barcode-observation'){const form=$('#barcode-observation-form');if(!form)return;const values=Object.fromEntries(new FormData(form).entries()),barcode=String(values.barcode||'').trim();if(barcode&&!validBarcode(barcode)){toast('Check the barcode digits before saving.');return}if(!String(values.name||'').trim()){toast('Add the exact pack name before saving.');return}state.barcodeObservations=[...state.barcodeObservations.slice(-99),{id:`obs-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,...values,barcode,recordedAt:new Date().toISOString(),status:'awaiting-review'}];persist();$('#detail-dialog').close();render();toast('Local pack observation saved')}});
document.addEventListener('change',e=>{if(e.target.id==='barcode-photo')scanPhoto(e.target.files[0])});
window.addEventListener('pagehide',stopCamera);
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'search_meat_catalogue',title:'Search Fieldfare products',description:'Search reviewed organic meat by default. Set organicOnly to false to include other sourcing candidates. Results expose evidence and limits, not live stock or batch approval.',inputSchema:{type:'object',properties:{query:{type:'string'},organicOnly:{type:'boolean'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(typeof input?.query!=='string'||input.query.length>200)throw new Error('Provide a query of up to 200 characters');if(input.organicOnly!==undefined&&typeof input.organicOnly!=='boolean')throw new Error('organicOnly must be boolean');return products.filter(p=>(input.organicOnly===false||hasOrganicListing(productReviews[p.id]))&&`${p.name} ${p.retailer} ${p.species}`.toLowerCase().includes(input.query.toLowerCase())).map(p=>({id:p.id,name:p.name,supplier:p.retailer,source:p.url,status:'sourcing_candidate',organicEvidence:organicEvidenceLabel(productReviews[p.id]),why:productReviews[p.id].why,limits:productReviews[p.id].limits}))}},{name:'add_products_to_shopping_list',title:'Add products to Fieldfare list',description:'Add known product IDs to the device-local shopping list. Does not place an order.',inputSchema:{type:'object',properties:{productIds:{type:'array',items:{type:'string'},minItems:1,maxItems:20}},required:['productIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!Array.isArray(input?.productIds)||!input.productIds.length||input.productIds.length>20||input.productIds.some(id=>typeof id!=='string'||!products.some(p=>p.id===id)))throw new Error('Use 1–20 valid catalogue product IDs');input.productIds.forEach(add);state.route='basket';if(location.hash!=='#basket')location.hash='basket';render();return {added:input.productIds,totalItems:count(),ordered:false}}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
render();registerTools();

function swapPanel(p){const swaps=alternatives(p,products,productReviews,state);return `<section class="swap-panel"><h3>${verdict(p).key==='meets'?'Other matches to consider':'Choose a better-documented option'}</h3><p>Same species, prioritising your supermarket. Stock is unconfirmed.</p>${swaps.length?swaps.map(q=>`<button class="swap-item" data-action="product" data-id="${q.id}"><span><b>${esc(q.name)}</b><small>${esc(q.retailer)} · ${q.retailer===p.retailer?'Same supermarket':'Different supermarket'}${cutOf(q)!==cutOf(p)?' · Different cut':''}${q.retailer==='Ocado'?' · Delivery area unconfirmed':''}</small></span>${icon('arrow-right')}</button>`).join(''):'<p>No confirmed alternative meets your current standard in this reviewed catalogue. We have not relaxed your preference.</p>'}</section>`}

// Product decisions are intentionally categorical. The former 0–100 coverage
// rubric made a well-documented indoor system look comparable with a match.
function scorePanel(p){const r=productReviews[p.id],d=verdict(p);return `<section class="evidence-summary"><p class="small-caps">EVIDENCE RECORD</p><h3>${esc(evidenceRecordLabel(p,r))}</h3><p>${p.identityStatus==='exact_variant'?'The cited evidence is tied to this named product. Still match the current pack before buying.':'This named product comes from a retailer category or range page. The shelf pack must repeat the organic, free-range or outdoor-bred claim.'}</p><div class="check-row"><b>Shopping decision</b><span class="verdict-pill ${d.tone}">${esc(d.label)}</span></div><div class="check-row"><b>Organic evidence</b><span>${esc(organicEvidenceLabel(r))}</span></div><div class="check-row"><b>Outdoor evidence</b><span>${p.outdoor===true?'Recorded':p.outdoor===false?'Indoor system recorded':'Not established'}</span></div></section>`}
function decisionMethod(){dialog('How Fieldfare makes a decision',`<p>The buying verdict comes first. It never uses a numerical welfare score.</p><div class="check-row"><b>Confirmed match</b><span>Exact product evidence supports organic outdoor meat, or an exact free-range / outdoor-bred product.</span></div><div class="check-row"><b>Pack check needed</b><span>A credible official claim exists, but you must confirm it on the current pack.</span></div><div class="check-row"><b>Evidence conflict — check the pack</b><span>The record is stale, conflicting, or needs a stronger certificate check.</span></div><div class="check-row"><b>Confirmed mismatch</b><span>The reviewed evidence records an indoor system while outdoor access is required.</span></div><div class="check-row"><b>Not enough evidence</b><span>No organic or outdoor claim was established. This is not a finding of poor welfare.</span></div><p class="method-note">“Exact product review” and “Pack check needed” describe how directly our evidence maps to the item, not how much an animal suffered.</p>`)}
function compareDialog(){const items=state.compare.map(id=>products.find(p=>p.id===id)).filter(Boolean);dialog('Compare the evidence',`<p>Compare the shopping decisions first, then the exact evidence record. Stock is not live.</p><div class="comparison-grid">${items.map(p=>{const r=productReviews[p.id],d=verdict(p);return `<section class="compare-product">${brand(p.retailer)}<span class="small-caps">${esc(p.retailer)}</span><h3>${esc(p.name)}</h3><span class="verdict-pill ${d.tone}">${d.label}</span><p>${esc(d.reason)}</p><dl><dt>Evidence record</dt><dd>${esc(evidenceRecordLabel(p,r))}</dd><dt>Organic evidence</dt><dd>${esc(organicEvidenceLabel(r))}</dd><dt>Outdoor evidence</dt><dd>${p.outdoor===false?'Indoor system':p.outdoor===true?'Outdoor / free-range claim':'Not established'}</dd><dt>Certifier / code</dt><dd>${esc(r.certifier||'Not established')}${r.code?' · '+esc(r.code):''}</dd><dt>Remaining check</dt><dd>${esc(r.limits)}</dd></dl><button class="btn small" data-action="product" data-id="${p.id}">Full evidence & swaps</button></section>`}).join('')}</div>`)}
function retailerScores(){dialog('Supermarket product coverage',`<p>These are catalogue counts, not supermarket welfare scores or stock estimates. Direct and conditional choices are kept separate.</p><button class="btn wide" data-action="published-rankings">${icon('chart-no-axes-combined')}See WWF & BBFAW published rankings</button><div class="retailer-score-list">${Object.keys(retailerReviews).sort().map(name=>{const c=retailerCoverage(name,products,productReviews,state);return `<button class="retailer-score-row" data-action="score-shop" data-value="${esc(name)}">${brand(name)}<span><b>${esc(name)}</b><small>${c.matches} confirmed matches · ${c.likely} pack checks · ${c.reviewed} catalogued</small></span>${icon('arrow-right')}</button>`}).join('')}</div><button class="text-button" data-action="decision-method">How these decisions work</button>`)}
function retiredNumericScoreLanguage(){const explainer=document.querySelector('.score-explainer');if(explainer){const copy=explainer.querySelector('span');if(copy)copy.textContent='Use the shopping decision first. “Exact product review” is tied to that item; “Pack check needed” means confirm the wording on the shelf.';const button=explainer.querySelector('button');if(button){button.dataset.action='decision-method';button.textContent='How decisions work'}}const sort=$('#sort-filter');if(sort){const option=[...sort.options].find(option=>option.value==='score');if(option){option.value='evidence';option.textContent='Exact reviews first'}if(state.sort==='score')state.sort='evidence';sort.value=state.sort}}
new MutationObserver(removeNumericScoreLanguage).observe(document.body,{childList:true,subtree:true});
const decisionStyles=document.createElement('style');decisionStyles.textContent='.evidence-badge{display:flex;align-items:center;gap:9px;width:100%;padding:10px 12px;margin:0 0 15px;border:1px solid #dfe5d7;border-radius:9px;background:#f5f6f1;color:var(--ink)}.evidence-badge.candidate{background:#fffaf0;border-color:#eadbb3}.evidence-badge svg{width:18px;flex:0 0 auto;color:var(--green)}.evidence-badge.candidate svg{color:#9a701f}.evidence-badge span{display:grid;gap:2px;font-size:12px}.evidence-badge small{font-size:11px;color:var(--muted)}.evidence-summary{padding:18px;background:#f5f6f1;border:1px solid #dfe5d7;border-radius:12px;margin:18px 0 24px}.evidence-summary h3{margin:5px 0 10px;font-size:20px}.evidence-summary>p{font-size:13px;margin:0 0 15px}';document.head.append(decisionStyles);
removeNumericScoreLanguage();
document.addEventListener('click',e=>{if(e.target.closest('[data-action="decision-method"]'))decisionMethod()});

// The catalogue re-renders often. Only change the DOM when it still contains the
// retired wording, otherwise the observer would create its own mutation loop.
function removeNumericScoreLanguage(){const explainer=document.querySelector('.score-explainer');if(explainer){const copy=explainer.querySelector('span'),message='Use the shopping decision first. “Exact product review” is tied to that item; “Pack check needed” means confirm the wording on the shelf.';if(copy&&copy.textContent!==message)copy.textContent=message;const button=explainer.querySelector('button');if(button&&button.dataset.action!=='decision-method'){button.dataset.action='decision-method';button.textContent='How decisions work'}}const sort=$('#sort-filter');if(sort){const option=[...sort.options].find(option=>option.value==='score');if(option){option.value='evidence';option.textContent='Exact reviews first'}if(state.sort==='score')state.sort='evidence';if(sort.value!==state.sort)sort.value=state.sort}}
function retiredCompareDialog(){const items=state.compare.map(id=>products.find(p=>p.id===id)).filter(Boolean);dialog('Compare the evidence',`<p>Exact products, assessed against the same organic preference. Stock is not live.</p><div class="comparison-grid">${items.map(p=>{const r=productReviews[p.id],d=verdict(p);return `<section class="compare-product">${brand(p.retailer)}<span class="small-caps">${esc(p.retailer)}</span><h3>${esc(p.name)}</h3><span class="verdict-pill ${d.tone}">${d.label}</span><p>${esc(d.reason)}</p><dl><dt>Evidence score</dt><dd>${evidenceScore(p,productReviews[p.id]).total}/100 · evidence coverage only</dd><dt>Organic evidence</dt><dd>${esc(organicEvidenceLabel(r))}</dd><dt>Outdoor evidence</dt><dd>${p.outdoor===false?'Indoor system':p.outdoor===true?'Outdoor / organic-system claim':'Not established'}</dd><dt>Certifier / code</dt><dd>${esc(r.certifier||'Not established')}${r.code?' · '+esc(r.code):''}</dd><dt>Certificate scope</dt><dd>Not independently checked</dd><dt>Availability</dt><dd>${p.availability==='unavailable'?'Listing showed unavailable':'Branch stock unknown'}</dd><dt>Remaining checks</dt><dd>${esc(r.limits)}</dd></dl><button class="btn small" data-action="product" data-id="${p.id}">Full evidence & swaps</button></section>`}).join('')}</div>`)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(a==='retailer'){state.retailer=el.dataset.value;state.scope='supermarkets';state.verdict='all';persist();render()}if(a==='verdict'){state.verdict=el.dataset.value;results()}if(a==='shop-profile'){const supplier=suppliers.find(s=>s.name===state.retailer);if(supplier)supplierDetail(supplier.id)}if(a==='compare-toggle'){if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<3)state.compare.push(id);else{toast('Compare up to three products. Clear one to add another.');return}results()}if(a==='compare-open')compareDialog();if(a==='compare-clear'){state.compare=[];results()}});

function retiredScorePanel(p){const score=evidenceScore(p,productReviews[p.id]);return `<section class="score-panel"><div class="score-panel-heading"><div><p class="small-caps">EVIDENCE FOR YOUR ORGANIC STANDARD</p><h3>Why ${score.total} out of 100?</h3></div><span class="score-total">${score.total}<small>/100</small></span></div><p>This measures documented evidence, not animal welfare outcomes. Your buying verdict is checked separately.</p><details><summary>See every point in the score</summary>${score.parts.map(part=>`<div class="score-part"><div><b>${esc(part.label)}</b><span>${part.points} / ${part.max}</span></div><progress max="${part.max}" value="${part.points}" aria-label="${esc(part.label)}: ${part.points} of ${part.max}"></progress><p>${esc(part.detail)}</p></div>`).join('')}<button class="text-button" data-action="score-method">Read the scoring method</button></details></section>`}
function scoringMethod(){dialog('What the scores mean',`<p>Fieldfare’s evidence score measures how much documented support we have for the organic shopping standard. It is an editorial rubric, not a validated welfare assessment or certification.</p><div class="check-row"><b>Exact organic product claim</b><span>25 points</span></div><div class="check-row"><b>Organic control code / certifier</b><span>25 for a code; 18 for a named body</span></div><div class="check-row"><b>Documented rearing system</b><span>15 points — indoor or outdoor</span></div><div class="check-row"><b>Linked primary sources</b><span>10 points</span></div><div class="check-row"><b>Recent, consistent record</b><span>10 points — within 90 days, no pack conflict</span></div><div class="check-row"><b>Independent product verification</b><span>10 for certificate scope + 5 for matched pack GTIN</span></div><p class="method-note">Documented indoor rearing earns evidence points but still fails your outdoor preference. An organic retailer claim is not an independently audited certificate. A missing fact earns no points; it does not prove poor welfare.</p><p>Scores cannot override your standards, confirm availability or approve a barcode. They may change when a source changes or becomes stale. Version 1 · published 22 September 2026.</p><h3>Supermarket coverage</h3><p>The percentage is matching reviewed products ÷ all reviewed products for that retailer. It changes with your standards and our sample. Small, selected samples are not comparable estimates of a supermarket’s entire range. We do not average product evidence scores into a chain-wide welfare score.</p>`)}
function retiredRetailerScores(){dialog('Supermarkets, by reviewed coverage',`<p>Organic outdoor products and exact free-range / outdoor-bred listings can match. “Pack check needed” means the retailer makes a credible claim but the current pack still needs to repeat it. These selected samples do not represent each supermarket’s full range, and stock is not confirmed.</p><button class="btn wide" data-action="published-rankings">${icon('chart-no-axes-combined')}See WWF & BBFAW published rankings</button><div class="retailer-score-list">${Object.keys(retailerReviews).sort().map(name=>{const c=retailerCoverage(name,products,productReviews,state);return `<button class="retailer-score-row" data-action="score-shop" data-value="${esc(name)}">${brand(name)}<span><b>${esc(name)}</b><small>${c.matches} direct · ${c.likely} likely* · ${c.reviewed} catalogued</small></span><strong>${c.matches+c.likely}</strong>${icon('arrow-right')}</button>`}).join('')}</div><button class="text-button" data-action="score-method">How these figures are calculated</button>`)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='score'){const p=products.find(p=>p.id===el.dataset.id);if(p)dialog(esc(p.name),scorePanel(p),`<button class="btn primary" data-action="product" data-id="${p.id}">Full evidence & alternatives</button>`)}if(el.dataset.action==='score-method')scoringMethod();if(el.dataset.action==='retailer-scores')retailerScores();if(el.dataset.action==='score-shop'){state.retailer=el.dataset.value;state.scope='supermarkets';state.category='All meat';state.search='';state.verdict='all';state.filter='all';state.onlySaved=false;persist();$('#detail-dialog').close();state.route='discover';if(location.hash!=='#discover')location.hash='discover';render()}});
